declare(strict_types=1);

namespace Magefan\Translation\Ui\DataProvider\Product\Form\Modifier;

use Magento\Catalog\Ui\DataProvider\Product\Form\Modifier\AbstractModifier;

/**
 * Applies the locked (upgrade teaser) component to the "Auto Translation (Extra)" product fieldset.
 *
 * The fieldset is generated by the EAV modifier from the attribute group of mf_exclude_auto_translation.
 * It must not be declared statically in product_form.xml: when the attribute is hidden (e.g. by
 * Adobe Commerce admin role attribute permissions) the group is not generated, and a static node
 * would be left without label/componentType, breaking the whole product form rendering.
 */
class LockedFieldset extends AbstractModifier
{
    /**
     * Code of the attribute group generated from the "Auto Translation (Extra)" group name.
     */
    public const FIELDSET_CODE = 'auto-translation-extra';

    /**
     * JS component of the locked fieldset.
     */
    public const COMPONENT = 'Magefan_Translation/js/form/components/locked-fieldset';

    /**
     * Data modification is not required.
     *
     * @param array $data
     * @return array
     */
    public function modifyData(array $data)
    {
        return $data;
    }

    /**
     * Set locked fieldset component only if the fieldset is present in meta.
     *
     * @param array $meta
     * @return array
     */
    public function modifyMeta(array $meta)
    {
        if (!isset($meta[self::FIELDSET_CODE]) || !is_array($meta[self::FIELDSET_CODE])) {
            return $meta;
        }

        $meta[self::FIELDSET_CODE]['arguments']['data']['config']['component'] = self::COMPONENT;

        return $meta;
    }
}
